                      '        let n ∈ Nat\n'
                      '            assume even n ∨ odd n\n'
                      '                assume even n\n'
                      '                    ∃ $k ($k ∈ Nat ∧ n = 2 * $k)\n'
                      '                    pick k with k ∈ Nat ∧ n = 2 * k\n'
                      '                        n = 2 * k\n'
                      '                        k ∈ Nat\n'
                      '                        n + 1 = 2 * k + 1\n'
                      '                        k ∈ Nat ∧ n + 1 = 2 * k + 1\n'
                      '                        ∃ $j ($j ∈ Nat ∧ n + 1 = 2 * $j '
                      '+ 1)\n'
                      '                        odd (n + 1)\n'
                      '                        even (n + 1) ∨ odd (n + 1)\n'
                      '                assume odd n\n'
                      '                    ∃ $k ($k ∈ Nat ∧ n = 2 * $k + 1)\n'
                      '                    pick k with k ∈ Nat ∧ n = 2 * k + '
                      '1\n'
                      '                        n = 2 * k + 1\n'
                      '                        k ∈ Nat\n'
                      '                        n + 1 = 2 * k + 1 + 1\n'
                      '                        calc on\n'
                      '                        n + 1 = 2 * k + 2\n'
                      '                        calc off\n'
                      '                        2 * (k + 1) = 2 * k + 2 * 1\n'
                      '                        calc on\n'
                      '                        2 * (k + 1) = 2 * k + 2\n'
                      '                        calc off\n'
                      '                        n + 1 = 2 * (k + 1)\n'
                      '                        k + 1 ∈ Nat\n'
                      '                        k + 1 ∈ Nat ∧ n + 1 = 2 * (k + '
                      '1)\n'
                      '                        ∃ $j ($j ∈ Nat ∧ n + 1 = 2 * '
                      '$j)\n'
                      '                        even (n + 1)\n'
                      '                        even (n + 1) ∨ odd (n + 1)\n'
                      '                even (n + 1) ∨ odd (n + 1)\n'
                      '    qed\n'
                      '    ; by induction (natural.kurt)\n'
                      'qed\n'
                      '\n'
                      '; 2 k = 2 j + 1 has no solution in Nat\n'
                      'show ∀ $k ∈ Nat ∀ $j ∈ Nat (2 * $k ≠ 2 * $j + 1)     '
                      '"even-ne-odd"\n'
                      'proof\n'
                      '    ; k = 0: 2 j + 1 ≠ 0\n'
                      '    let j ∈ Nat\n'
                      '        2 * j ∈ Nat\n'
                      '        2 * j + 1 ≠ 0                                 ; '
                      'nat-succ-ne-zero\n'
