                      '            let j ∈ Nat\n'
                      '                assume 2 * (k + 1) = 2 * j + 1\n'
                      '                    j = 0 ∨ ∃ $m ($m ∈ Nat ∧ j = $m + '
                      '1)       ; nat-zero-or-succ\n'
                      '                    case j = 0\n'
                      '                        2 * k + 2 * 1 = 2 * (k + 1)\n'
                      '                                      = 2 * j + 1\n'
                      '                                      = 2 * 0 + 1\n'
                      '                        2 * k + 2 * 1 + (- 1) = 2 * 0 + '
                      '1 + (- 1)\n'
                      '                        calc on\n'
                      '                        2 * k + 1 = 0\n'
                      '                        calc off\n'
                      '                        2 * k + 1 ≠ '
                      '0                         ; nat-succ-ne-zero\n'
                      '                        ¬(2 * k + 1 = 0)\n'
                      '                        2 * k + 1 = 0 ∧ ¬(2 * k + 1 = '
                      '0)\n'
                      '                        ⊥\n'
