                      'm + 2 * 1 + 1 + (- 2)\n'
                      '                            calc on\n'
                      '                            2 * k = 2 * m + 1\n'
                      '                            calc off\n'
                      '                            2 * k ≠ 2 * m + 1\n'
                      '                            ¬(2 * k = 2 * m + 1)\n'
                      '                            2 * k = 2 * m + 1 ∧ ¬(2 * k '
                      '= 2 * m + 1)\n'
                      '                            ⊥\n'
                      '                    ⊥\n'
                      '                ¬(2 * (k + 1) = 2 * j + 1)\n'
                      '                2 * (k + 1) ≠ 2 * j + 1\n'
                      '            ∀ $j ∈ Nat (2 * (k + 1) ≠ 2 * $j + 1)\n'
                      '    ∀ $k ∈ Nat (∀ $j ∈ Nat (2 * $k ≠ 2 * $j + 1)  ⇒  ∀ '
                      '$j ∈ Nat (2 * ($k + 1) ≠ 2 * $j + 1))\n'
                      '    (∀ $j ∈ Nat (2 * 0 ≠ 2 * $j + 1)) ∧ ∀ $k ∈ Nat (∀ '
                      '$j ∈ Nat (2 * $k ≠ 2 * $j + 1)  ⇒  ∀ $j ∈ Nat (2 * ($k '
                      '+ 1) ≠ 2 * $j + 1))\n'
                      '    ∀ $k ∈ Nat ∀ $j ∈ Nat (2 * $k ≠ 2 * $j + 1)\n'
                      'qed\n'
                      '\n'
                      '; no number is even and odd\n'
                      'show ¬(even $m ∧ odd $m)     "not-even-and-odd"\n'
                      'proof\n'
                      '    assume even $m ∧ odd $m\n'
                      '        even $m\n'
                      '        odd $m\n'
                      '        ∃ $k ($k ∈ Nat ∧ $m = 2 * $k)\n'
                      '        ∃ $k ($k ∈ Nat ∧ $m = 2 * $k + 1)\n'
                      '        pick k with k ∈ Nat ∧ $m = 2 * k\n'
