                      '                      = 2 * j + 1\n'
                      '                ∀ $j ∈ Nat (2 * k ≠ 2 * $j + 1)        '
                      '; even-ne-odd\n'
                      '                2 * k ≠ 2 * j + 1\n'
                      '                ¬(2 * k = 2 * j + 1)\n'
                      '                2 * k = 2 * j + 1 ∧ ¬(2 * k = 2 * j + '
                      '1)\n'
                      '                ⊥\n'
                      'qed\n'
                      '\n'
                      '; the square of an odd number is odd: m m = (2k+1) m = '
                      '2 k m + m = 2 (k m + k) + 1\n'
                      'show $m ∈ Nat ∧ odd $m  ⇒  odd ($m * $m)   '
                      '"odd-square"\n'
                      'proof\n'
                      '    assume $m ∈ Nat ∧ odd $m\n'
                      '        odd $m\n'
                      '        ∃ $k ($k ∈ Nat ∧ $m = 2 * $k + 1)\n'
                      '        pick k with k ∈ Nat ∧ $m = 2 * k + 1\n'
                      '            $m = 2 * k + 1\n'
                      '            k ∈ Nat\n'
                      '            $m ∈ Nat\n'
                      '            $m * $m = (2 * k + 1) * $m\n'
                      '                    = 2 * k * $m + 1 * $m\n'
                      '                    = 2 * k * $m + $m\n'
                      '                    = 2 * k * $m + (2 * k + 1)\n'
                      '                    = 2 * k * $m + 2 * k + 1\n'
                      '                    = 2 * (k * $m + k) + 1\n'
                      '            k * $m ∈ Nat\n'
                      '            k * $m + k ∈ Nat\n'
                      '            k * $m + k ∈ Nat ∧ $m * $m = 2 * (k * $m + '
                      'k) + 1\n'
                      '            ∃ $j ($j ∈ Nat ∧ $m * $m = 2 * $j + 1)\n'
                      '            odd ($m * $m)\n'
                      'qed\n'
                      '\n'
                      '; if the square is even, so is the number: otherwise it '
                      'is odd, and so is its square\n'
                      'show $m ∈ Nat ∧ even ($m * $m)  ⇒  even $m   '
                      '"even-square"\n'
                      'proof\n'
                      '    assume $m ∈ Nat ∧ even ($m * $m)\n'
                      '        $m ∈ Nat\n'
                      '        even $m ∨ odd $m                               '
                      '; even-or-odd\n'
                      '        assume even $m\n'
                      '            even $m\n'
                      '        assume odd $m\n'
                      '            odd ($m * $m)                              '
                      '; odd-square\n'
