                      '            false                                      '
                      '; not-even-and-odd\n'
                      '            even $m\n'
                      '        even $m                                        '
                      '; or-elim\n'
                      'qed\n'
                      '\n'
                      ';; divisibility\n'
                      'infix divides 20 20\n'
                      'prop divides 0\n'
                      'alias ∣ divides\n'
                      'def $a ∣ $b  ⇔  ∃ $k ($k ∈ Nat ∧ $b = $a * $k)       '
                      '"divides"\n'
                      '\n'
                      'show $a ∈ Nat  ⇒  $a ∣ $a     "divides-refl"\n'
                      'proof\n'
                      '    assume $a ∈ Nat\n'
                      '        1 ∈ Nat\n'
                      '        $a = $a * 1\n'
                      '        1 ∈ Nat ∧ $a = $a * 1\n'
                      '        ∃ $k ($k ∈ Nat ∧ $a = $a * $k)\n'
                      '        $a ∣ $a\n'
                      'qed\n'
                      '\n'
                      'show $a ∈ Nat  ⇒  1 ∣ $a     "one-divides"\n'
                      'proof\n'
                      '    assume $a ∈ Nat\n'
                      '        $a = 1 * $a\n'
                      '        $a ∈ Nat ∧ $a = 1 * $a\n'
                      '        ∃ $k ($k ∈ Nat ∧ $a = 1 * $k)\n'
                      '        1 ∣ $a\n'
                      'qed\n'
                      '\n'
                      'show $a ∣ $b ∧ $b ∣ $c  ⇒  $a ∣ $c     "divides-trans"\n'
                      'proof\n'
                      '    assume $a ∣ $b ∧ $b ∣ $c\n'
                      '        $a ∣ $b\n'
                      '        $b ∣ $c\n'
                      '        ∃ $k ($k ∈ Nat ∧ $b = $a * $k)\n'
                      '        ∃ $k ($k ∈ Nat ∧ $c = $b * $k)\n'
                      '        pick k with k ∈ Nat ∧ $b = $a * k\n'
                      '            k ∈ Nat\n'
