                      '                ∃ $l ($l ∈ Nat ∧ $c = $a * $l)\n'
                      '                $a ∣ $c\n'
                      'qed\n'
                      '\n'
                      '; even means divisible by 2\n'
                      'show even $m  ⇔  2 ∣ $m     "even-divides"\n'
                      'proof\n'
                      '    assume even $m\n'
                      '        ∃ $k ($k ∈ Nat ∧ $m = 2 * $k)\n'
                      '        2 ∣ $m\n'
                      '    assume 2 ∣ $m\n'
                      '        ∃ $k ($k ∈ Nat ∧ $m = 2 * $k)\n'
                      '        even $m\n'
                      'qed\n'
                      '\n'
                      '; coprime: 1 is the only common divisor\n'
                      'arity coprime (_, _)\n'
                      'def coprime($a, $b)  ⇔  ∀ $d ∈ Nat ($d ∣ $a ∧ $d ∣ $b  '
                      '⇒  $d = 1)     "coprime"\n'
                      '\n'
                      'show coprime($a, $b)  ⇒  ¬(even $a ∧ even $b)     '
