                      '                n ∈ Nat ∧ n ≠ 0 ∧ ∃ $i ($i ∈ Nat ∧ $q = '
                      '$i / n)\n'
                      '                n ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ '
                      'Nat ∧ $q = $i / $j) }     ; separation\n'
                      '                ∃ $x ($x ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i '
                      '($i ∈ Nat ∧ $q = $i / $j) })\n'
                      '        ∃ $x ($x ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ Nat '
                      '∧ $q = $i / $j) })\n'
                      '        { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ Nat ∧ $q = $i '
                      '/ $j) } ⊂ Nat ∧ ∃ $x ($x ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i '
                      '($i ∈ Nat ∧ $q = $i / $j) })\n'
                      '        ; the least one\n'
                      '        ∃ $l ($l ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ Nat '
                      '∧ $q = $i / $j) } ∧ ∀ $y ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i '
                      '($i ∈ Nat ∧ $q = $i / $j) } ($l <= $y))   ; '
                      'well-ordering\n'
