                      '            n ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ Nat ∧ '
                      '$q = $i / $j) }\n'
                      '            ∀ $y ∈ { $j ∈ Nat | $j ≠ 0 ∧ ∃ $i ($i ∈ Nat '
                      '∧ $q = $i / $j) } (n <= $y)\n'
                      '            n ∈ Nat ∧ n ≠ 0 ∧ ∃ $i ($i ∈ Nat ∧ $q = $i '
                      '/ n)     ; separation\n'
                      '            n ∈ Nat\n'
                      '            n ≠ 0\n'
                      '            ∃ $i ($i ∈ Nat ∧ $q = $i / n)\n'
                      '            pick m with m ∈ Nat ∧ $q = m / n\n'
                      '                m ∈ Nat\n'
                      '                $q = m / n\n'
                      '                ; m and n are coprime\n'
                      '                let d ∈ Nat\n'
                      '                    assume d ∣ m ∧ d ∣ n\n'
                      '                        d ∣ m\n'
                      '                        d ∣ n\n'
                      '                        ∃ $k ($k ∈ Nat ∧ m = d * $k)\n'
                      '                        ∃ $k ($k ∈ Nat ∧ n = d * $k)\n'
                      '                        pick a with a ∈ Nat ∧ m = d * '
                      'a\n'
                      '                            a ∈ Nat\n'
                      '                            m = d * a\n'
                      '                            pick b with b ∈ Nat ∧ n = d '
                      '* b\n'
                      '                                b ∈ Nat\n'
                      '                                n = d * b\n'
                      '                                ; d ≠ 0 and b ≠ 0, '
                      'since n ≠ 0\n'
                      '                                assume d = 0\n'
                      '                                    n = 0 * b\n'
                      '                                    n = '
                      '0                      ; mul-zero\n'
                      '                                    ¬(n = 0)\n'
                      '                                    n = 0 ∧ ¬(n = 0)\n'
                      '                                    ⊥\n'
                      '                                ¬(d = 0)\n'
                      '                                d ≠ 0\n'
