                      '                                    n = d * 0\n'
                      '                                    n = '
                      '0                      ; mul-zero\n'
                      '                                    ¬(n = 0)\n'
                      '                                    n = 0 ∧ ¬(n = 0)\n'
                      '                                    ⊥\n'
                      '                                ¬(b = 0)\n'
                      '                                b ≠ 0\n'
                      '                                ; so q = a / b, and b '
                      'is a denominator too\n'
                      '                                (d * a) / (d * b) = a / '
                      'b      ; frac-cancel\n'
                      '                                $q = m / n\n'
                      '                                   = (d * a) / n\n'
                      '                                   = (d * a) / (d * b)\n'
                      '                                   = a / b\n'
                      '                                a ∈ Nat ∧ $q = a / b\n'
                      '                                ∃ $i ($i ∈ Nat ∧ $q = '
                      '$i / b)\n'
                      '                                b ∈ Nat ∧ b ≠ 0 ∧ ∃ $i '
                      '($i ∈ Nat ∧ $q = $i / b)\n'
                      '                                b ∈ { $j ∈ Nat | $j ≠ 0 '
                      '∧ ∃ $i ($i ∈ Nat ∧ $q = $i / $j) }     ; separation\n'
                      '                                n <= b\n'
                      '                                ; d = 1, since d ≥ 2 '
                      'would make b < d b = n\n'
                      '                                assume ¬(d = 1)\n'
                      '                                    d ≠ 1\n'
                      '                                    2 <= '
                      'd                     ; nat-ge-two\n'
                      '                                    b < d * '
                      'b                  ; nat-lt-mul\n'
                      '                                    b < n\n'
                      '                                    b >= '
                      'n                     ; le-ge\n'
                      '                                    b < n ∧ b >= n\n'
                      '                                    '
                      '⊥                          ; lt-ge-contra\n'
                      '                                ¬¬(d = 1)\n'
                      '                                d = 1\n'
                      '                ∀ $d ∈ Nat ($d ∣ m ∧ $d ∣ n  ⇒  $d = '
                      '1)\n'
                      '                coprime(m, n)\n'
                      '                m ∈ Nat ∧ n ∈ Nat ∧ n ≠ 0 ∧ coprime(m, '
                      'n) ∧ $q = m / n\n'
                      '                ∃ $j (m ∈ Nat ∧ $j ∈ Nat ∧ $j ≠ 0 ∧ '
                      'coprime(m, $j) ∧ $q = m / $j)\n'
                      '                ∃ $i ∃ $j ($i ∈ Nat ∧ $j ∈ Nat ∧ $j ≠ 0 '
                      '∧ coprime($i, $j) ∧ $q = $i / $j)\n'
                      'qed\n'
