                '        ¬($x ∈ {$a})\n'
                '        $x ∈ $X ∧ ¬($x ∈ {$a})\n'
                '        $x ∈ $X ∖ {$a}                                 ; '
                'in-setminus\n'
                'qed\n'
                '\n'
                'show $x ∈ $X ∖ {$a}  ⇒  $x ∈ $X ∧ $x ≠ '
                '$a                              "in-remove-elim"\n'
                'proof\n'
                '    assume $x ∈ $X ∖ {$a}\n'
