                '                0 = n\n'
                '            0 = n\n'
                '    ∀ $P ∀ $j (hassize($P, 0) ∧ hassize($P, $j)  ⇒  0 = $j)\n'
                '    ; k → k + 1: remove an element a, X ∖ {a} has k and n - 1 '
                'elements\n'
                '    let k ∈ Nat\n'
                '        assume ∀ $P ∀ $j (hassize($P, k) ∧ hassize($P, $j)  '
                '⇒  k = $j)\n'
                '            let X, n\n'
                '                set X\n'
                '                real n\n'
                '                assume hassize(X, k + 1) ∧ hassize(X, n)\n'
                '                    hassize(X, k + 1)\n'
                '                    hassize(X, n)\n'
                '                    n ∈ Nat ∧ ∃ $m bijection($m, below(n), '
                'X)     ; hassize\n'
                '                    n ∈ Nat\n'
                '                    k + 1 ≠ 0                          ; '
                'nat-succ-ne-zero\n'
                '                    hassize(X, k + 1) ∧ k + 1 ≠ 0\n'
                '                    ∃ x (x ∈ X)                        ; '
                'hassize-nonempty\n'
                '                    pick a with a ∈ X\n'
                '                        k ∈ Nat ∧ hassize(X, k + 1) ∧ a ∈ X\n'
                '                        hassize(X ∖ {a}, k)            ; '
                'hassize-remove\n'
                '                        assume n = 0\n'
                '                            hassize(X, 0)\n'
                '                            X = ∅                      ; '
                'hassize-zero\n'
                '                            a ∈ ∅\n'
                '                            ⊥                          ; '
                'empty-set\n'
                '                        n ≠ 0\n'
                '                        n ∈ Nat ∧ n ≠ 0\n'
                '                        ∃ i (i ∈ Nat ∧ n = i + 1)      ; '
                'nat-pred\n'
                '                        pick i with i ∈ Nat ∧ n = i + 1\n'
                '                            i ∈ Nat\n'
                '                            n = i + 1\n'
                '                            hassize(X, i + 1)\n'
                '                            i ∈ Nat ∧ hassize(X, i + 1) ∧ a ∈ '
                'X\n'
                '                            hassize(X ∖ {a}, i)        ; '
                'hassize-remove\n'
                '                            hassize(X ∖ {a}, k) ∧ hassize(X ∖ '
                '{a}, i)  ⇒  k = i\n'
                '                            hassize(X ∖ {a}, k) ∧ hassize(X ∖ '
                '{a}, i)\n'
                '                            k = i\n'
                '                            k + 1 = i + 1\n'
                '                            k + 1 = n\n'
                '            ∀ $P ∀ $j (hassize($P, k + 1) ∧ hassize($P, $j)  '
                '⇒  k + 1 = $j)\n'
                '    ∀ k ∈ Nat (∀ $P ∀ $j (hassize($P, k) ∧ hassize($P, $j)  '
                '⇒  k = $j)  ⇒  ∀ $P ∀ $j (hassize($P, k + 1) ∧ hassize($P, '
                '$j)  ⇒  k + 1 = $j))\n'
                '    (∀ $P ∀ $j (hassize($P, 0) ∧ hassize($P, $j)  ⇒  0 = $j)) '
                '∧ ∀ k ∈ Nat (∀ $P ∀ $j (hassize($P, k) ∧ hassize($P, $j)  ⇒  '
                'k = $j)  ⇒  ∀ $P ∀ $j (hassize($P, k + 1) ∧ hassize($P, $j)  '
                '⇒  k + 1 = $j))\n'
                '    ∀ $i ∈ Nat ∀ $P ∀ $j (hassize($P, $i) ∧ hassize($P, $j)  '
                '⇒  $i = $j)     ; induction\n'
                '    assume hassize($X, $k) ∧ hassize($X, $n)\n'
                '        hassize($X, $k)\n'
                '        $k ∈ Nat ∧ ∃ $m bijection($m, below($k), $X)    ; '
                'hassize\n'
                '        $k ∈ Nat\n'
                '        ∀ $P ∀ $j (hassize($P, $k) ∧ hassize($P, $j)  ⇒  $k = '
                '$j)\n'
                '        hassize($X, $k) ∧ hassize($X, $n)  ⇒  $k = $n\n'
                '        $k = $n\n'
                'qed\n'
                '\n'
                'show ($X ∪ $Y) ∪ $Z = $X ∪ ($Y ∪ '
                '$Z)                                  "union-assoc"\n'
                'proof\n'
                '    let c\n'
                '        assume c ∈ ($X ∪ $Y) ∪ $Z\n'
                '            c ∈ $X ∪ $Y ∨ c ∈ $Z                       ; '
                'union\n'
                '            case c ∈ $X ∪ $Y\n'
                '                c ∈ $X ∨ c ∈ $Y                        ; '
                'union\n'
                '                case c ∈ $X\n'
                '                    c ∈ $X ∨ c ∈ $Y ∪ $Z\n'
                '                case c ∈ $Y\n'
                '                    c ∈ $Y ∨ c ∈ $Z\n'
                '                    c ∈ $Y ∪ $Z                        ; '
                'union\n'
                '                    c ∈ $X ∨ c ∈ $Y ∪ $Z\n'
                '                c ∈ $X ∨ c ∈ $Y ∪ $Z\n'
                '            case c ∈ $Z\n'
                '                c ∈ $Y ∨ c ∈ $Z\n'
                '                c ∈ $Y ∪ $Z                            ; '
                'union\n'
                '                c ∈ $X ∨ c ∈ $Y ∪ $Z\n'
                '            c ∈ $X ∨ c ∈ $Y ∪ $Z\n'
                '            c ∈ $X ∪ ($Y ∪ $Z)                         ; '
                'union\n'
                '        assume c ∈ $X ∪ ($Y ∪ $Z)\n'
                '            c ∈ $X ∨ c ∈ $Y ∪ $Z                       ; '
                'union\n'
                '            case c ∈ $X\n'
                '                c ∈ $X ∨ c ∈ $Y\n'
                '                c ∈ $X ∪ $Y                            ; '
                'union\n'
                '                c ∈ $X ∪ $Y ∨ c ∈ $Z\n'
                '            case c ∈ $Y ∪ $Z\n'
                '                c ∈ $Y ∨ c ∈ $Z                        ; '
                'union\n'
                '                case c ∈ $Y\n'
                '                    c ∈ $X ∨ c ∈ $Y\n'
                '                    c ∈ $X ∪ $Y                        ; '
                'union\n'
                '                    c ∈ $X ∪ $Y ∨ c ∈ $Z\n'
                '                case c ∈ $Z\n'
                '                    c ∈ $X ∪ $Y ∨ c ∈ $Z\n'
                '                c ∈ $X ∪ $Y ∨ c ∈ $Z\n'
                '            c ∈ $X ∪ $Y ∨ c ∈ $Z\n'
                '            c ∈ ($X ∪ $Y) ∪ $Z                         ; '
                'union\n'
                '        c ∈ ($X ∪ $Y) ∪ $Z  ⇔  c ∈ $X ∪ ($Y ∪ $Z)\n'
                '    ∀ c (c ∈ ($X ∪ $Y) ∪ $Z  ⇔  c ∈ $X ∪ ($Y ∪ $Z))\n'
                '    ($X ∪ $Y) ∪ $Z = $X ∪ ($Y ∪ $Z)                    ; '
                'extensionality\n'
                'qed\n'
                '\n'
                '; X ∖ {b} and {b} put together again\n'
                'show $b ∈ $Y  ⇒  ($Y ∖ {$b}) ∪ {$b} = '
                '$Y                             "remove-add"\n'
                'proof\n'
                '    assume $b ∈ $Y\n'
                '        let c\n'
                '            assume c ∈ ($Y ∖ {$b}) ∪ {$b}\n'
                '                c ∈ $Y ∖ {$b} ∨ c ∈ {$b}               ; '
                'union\n'
                '                case c ∈ $Y ∖ {$b}\n'
                '                    c ∈ $Y ∧ c ≠ $b                    ; '
                'in-remove-elim\n'
                '                    c ∈ $Y\n'
                '                case c ∈ {$b}\n'
                '                    c = $b                             ; '
                'singleton\n'
                '                    c ∈ $Y\n'
                '                c ∈ $Y\n'
                '            assume c ∈ $Y\n'
                '                c = $b ∨ c ≠ $b                        ; '
                'excluded-middle\n'
                '                case c = $b\n'
                '                    c ∈ {$b}                           ; '
                'singleton\n'
                '                    c ∈ $Y ∖ {$b} ∨ c ∈ {$b}\n'
                '                case c ≠ $b\n'
                '                    c ∈ $Y ∧ c ≠ $b\n'
                '                    c ∈ $Y ∖ {$b}                      ; '
                'in-remove\n'
                '                    c ∈ $Y ∖ {$b} ∨ c ∈ {$b}\n'
                '                c ∈ $Y ∖ {$b} ∨ c ∈ {$b}\n'
                '                c ∈ ($Y ∖ {$b}) ∪ {$b}                 ; '
                'union\n'
                '            c ∈ ($Y ∖ {$b}) ∪ {$b}  ⇔  c ∈ $Y\n'
                '        ∀ c (c ∈ ($Y ∖ {$b}) ∪ {$b}  ⇔  c ∈ $Y)\n'
                '        ($Y ∖ {$b}) ∪ {$b} = $Y                        ; '
                'extensionality\n'
                'qed\n'
                '\n'
                "; removing what isn't there changes nothing\n"
                'show ¬($b ∈ $Y)  ⇒  $Y ∖ {$b} = '
                '$Y                                    "remove-absent"\n'
                'proof\n'
                '    assume ¬($b ∈ $Y)\n'
                '        let c\n'
                '            assume c ∈ $Y ∖ {$b}\n'
                '                c ∈ $Y ∧ c ≠ $b                        ; '
                'in-remove-elim\n'
                '                c ∈ $Y\n'
                '            assume c ∈ $Y\n'
                '                assume c = $b\n'
