                '    assume hassize($X, $k) ∧ hassize($Y, $n) ∧ $X ∩ $Y = ∅\n'
                '        hassize($X, $k)\n'
                '        hassize($Y, $n)\n'
                '        $X ∩ $Y = ∅\n'
                '        $n ∈ Nat ∧ ∃ $m bijection($m, below($n), $Y)    ; '
                'hassize\n'
                '        $n ∈ Nat\n'
                '        ; n = 0: Y is empty\n'
                '        let Y\n'
                '            assume hassize(Y, 0) ∧ $X ∩ Y = ∅\n'
