                'Y                 ; in-intersection\n'
                '                                    b ∈ ∅\n'
                '                                    '
                '⊥                          ; empty-set\n'
                '                                case b ∈ Y ∖ {b}\n'
                '                                    b ∈ Y ∧ b ≠ '
                'b              ; in-remove-elim\n'
                '                                    b ≠ b\n'
                '                                    ⊥\n'
                '                                ⊥\n'
                '                            ¬(b ∈ $X ∪ (Y ∖ {b}))\n'
                '                            hassize($X ∪ (Y ∖ {b}), $k + i) ∧ '
                '¬(b ∈ $X ∪ (Y ∖ {b}))\n'
