                '\n'
                '; a subset of a set with n elements has at most n elements -- '
                'by induction on n, for all X and Y\n'
                'show hassize($X, $n) ∧ $Y ⊂ $X  ⇒  ∃ i (i <= $n ∧ hassize($Y, '
                'i))     "hassize-subset"\n'
                'proof\n'
                '    ; n = 0: X is empty, and so is Y\n'
                '    let X, Y\n'
                '        assume hassize(X, 0) ∧ Y ⊂ X\n'
                '            hassize(X, 0)\n'
                '            Y ⊂ X\n'
                '            X = ∅                                      ; '
                'hassize-zero\n'
                '            ∀ c (c ∈ Y  ⇒  c ∈ X)                      ; '
                'subset\n'
                '            let c\n'
                '                assume c ∈ Y\n'
                '                    c ∈ Y  ⇒  c ∈ X\n'
                '                    c ∈ X\n'
                '                    c ∈ ∅\n'
                '                assume c ∈ ∅\n'
                '                    ⊥                                  ; '
                'empty-set\n'
                '                    c ∈ Y\n'
                '                c ∈ Y  ⇔  c ∈ ∅\n'
                '            ∀ c (c ∈ Y  ⇔  c ∈ ∅)\n'
                '            Y = ∅                                      ; '
                'extensionality\n'
                '            hassize(∅, 0)                              ; '
                'hassize-empty\n'
                '            hassize(Y, 0)\n'
                '            0 <= 0                                     ; '
                'le-refl\n'
                '            0 <= 0 ∧ hassize(Y, 0)\n'
                '            ∃ i (i <= 0 ∧ hassize(Y, i))\n'
                '    ∀ X ∀ Y (hassize(X, 0) ∧ Y ⊂ X  ⇒  ∃ i (i <= 0 ∧ '
                'hassize(Y, i)))\n'
                '    ; n → n + 1: take an element a out of X (and out of Y)\n'
                '    let n ∈ Nat\n'
                '        assume ∀ X ∀ Y (hassize(X, n) ∧ Y ⊂ X  ⇒  ∃ i (i <= n '
                '∧ hassize(Y, i)))\n'
                '            n <= n + 1                                 ; '
                'lt-le\n'
                '            let X, Y\n'
                '                assume hassize(X, n + 1) ∧ Y ⊂ X\n'
                '                    hassize(X, n + 1)\n'
                '                    Y ⊂ X\n'
                '                    ∀ c (c ∈ Y  ⇒  c ∈ X)              ; '
                'subset\n'
                '                    n + 1 ≠ 0                          ; '
                'nat-succ-ne-zero\n'
                '                    hassize(X, n + 1) ∧ n + 1 ≠ 0\n'
                '                    ∃ x (x ∈ X)                        ; '
                'hassize-nonempty\n'
                '                    pick a with a ∈ X\n'
                '                        n ∈ Nat ∧ hassize(X, n + 1) ∧ a ∈ X\n'
                '                        hassize(X ∖ {a}, n)            ; '
                'hassize-remove\n'
                '                        let c\n'
                '                            assume c ∈ Y ∖ {a}\n'
                '                                c ∈ Y ∧ c ≠ a          ; '
                'in-remove-elim\n'
                '                                c ∈ Y\n'
                '                                c ≠ a\n'
                '                                c ∈ Y  ⇒  c ∈ X\n'
                '                                c ∈ X\n'
                '                                c ∈ X ∧ c ≠ a\n'
                '                                c ∈ X ∖ {a}            ; '
                'in-remove\n'
                '                        ∀ c (c ∈ Y ∖ {a}  ⇒  c ∈ X ∖ {a})\n'
                '                        Y ∖ {a} ⊂ X ∖ {a}\n'
                '                        hassize(X ∖ {a}, n) ∧ Y ∖ {a} ⊂ X ∖ '
                '{a}  ⇒  ∃ i (i <= n ∧ hassize(Y ∖ {a}, i))\n'
                '                        hassize(X ∖ {a}, n) ∧ Y ∖ {a} ⊂ X ∖ '
                '{a}\n'
                '                        ∃ i (i <= n ∧ hassize(Y ∖ {a}, i))\n'
                '                        pick i with i <= n ∧ hassize(Y ∖ {a}, '
                'i)\n'
                '                            i <= n\n'
                '                            hassize(Y ∖ {a}, i)\n'
                '                            a ∈ Y ∨ ¬(a ∈ Y)           ; '
                'excluded-middle\n'
                '                            case a ∈ Y\n'
                '                                assume a ∈ Y ∖ {a}\n'
                '                                    a ∈ Y ∧ a ≠ a      ; '
                'in-remove-elim\n'
                '                                    a ≠ a\n'
                '                                    ⊥\n'
                '                                ¬(a ∈ Y ∖ {a})\n'
                '                                hassize(Y ∖ {a}, i) ∧ ¬(a ∈ Y '
                '∖ {a})\n'
                '                                hassize((Y ∖ {a}) ∪ {a}, i + '
                '1)    ; hassize-add\n'
                '                                (Y ∖ {a}) ∪ {a} = Y    ; '
                'remove-add\n'
                '                                hassize(Y, i + 1)\n'
                '                                i + 1 <= n + 1         ; '
                'le-add\n'
                '                                i + 1 <= n + 1 ∧ hassize(Y, i '
                '+ 1)\n'
                '                                ∃ j (j <= n + 1 ∧ hassize(Y, '
                'j))\n'
